-- Book Library — full database schema.
-- Run this once in Supabase: SQL Editor -> New query -> paste -> Run.
-- Safe to run again; it skips anything that already exists.

-- ---------------------------------------------------------------------------
-- Better Auth tables (users, sessions, linked accounts, email verification).
-- Generated by the Better Auth CLI, so the names match what the library expects.
-- ---------------------------------------------------------------------------

create table if not exists public."user" (
  id              text        primary key,
  name            text        not null,
  email           text        not null unique,
  "emailVerified" boolean     not null default false,
  image           text,
  "createdAt"     timestamptz not null default current_timestamp,
  "updatedAt"     timestamptz not null default current_timestamp
);

create table if not exists public.session (
  id          text        primary key,
  "expiresAt" timestamptz not null,
  token       text        not null unique,
  "createdAt" timestamptz not null default current_timestamp,
  "updatedAt" timestamptz not null,
  "ipAddress" text,
  "userAgent" text,
  "userId"    text        not null references public."user"(id) on delete cascade
);

create table if not exists public.account (
  id                      text        primary key,
  "accountId"             text        not null,
  "providerId"            text        not null,
  "userId"                text        not null references public."user"(id) on delete cascade,
  "accessToken"           text,
  "refreshToken"          text,
  "idToken"               text,
  "accessTokenExpiresAt"  timestamptz,
  "refreshTokenExpiresAt" timestamptz,
  scope                   text,
  password                text,
  "createdAt"             timestamptz not null default current_timestamp,
  "updatedAt"             timestamptz not null
);

create table if not exists public.verification (
  id          text        primary key,
  identifier  text        not null,
  value       text        not null,
  "expiresAt" timestamptz not null,
  "createdAt" timestamptz not null default current_timestamp,
  "updatedAt" timestamptz not null default current_timestamp
);

create index if not exists "session_userId_idx"       on public.session    using btree ("userId");
create index if not exists "account_userId_idx"       on public.account    using btree ("userId");
create index if not exists verification_identifier_idx on public.verification using btree (identifier);

-- ---------------------------------------------------------------------------
-- Books. Each row belongs to one user; deleting the user removes their books.
-- ---------------------------------------------------------------------------

create table if not exists public.books (
  id         bigint generated always as identity primary key,
  user_id    text        not null references public."user"(id) on delete cascade,
  title      text        not null,
  author     text        not null,
  image      text        not null default '',
  available  boolean     not null default true,
  genre      text        not null default 'Other',
  rating     smallint    not null default 0 check (rating between 0 and 5),
  created_at timestamptz not null default now()
);

create index if not exists books_user_id_idx on public.books using btree (user_id);

-- ---------------------------------------------------------------------------
-- Lock the tables down.
-- The app connects straight to Postgres with DATABASE_URL, so it is unaffected.
-- Row Level Security with no policies blocks Supabase's public API keys
-- entirely, which is what we want: nothing should reach these tables except
-- the app itself.
-- ---------------------------------------------------------------------------

alter table public.books        enable row level security;
alter table public."user"       enable row level security;
alter table public.session      enable row level security;
alter table public.account      enable row level security;
alter table public.verification enable row level security;

-- Older versions of this project left the books table open. Clear those.
drop policy if exists "Public read access"   on public.books;
drop policy if exists "Public insert access" on public.books;
drop policy if exists "Public update access" on public.books;
drop policy if exists "Public delete access" on public.books;
